window.DOSIK=window.DOSIK||{};DOSIK["sb_otsu6_law"]={"1":[{"t":"table","title":"消防法の用語","head":["用語","定義"],"rows":[["無窓階","地上階のうち、避難上又は消火活動上有効な開口部を有しない階をいう"],["防火対象物","山林又は舟車、船きよ若しくはふ頭に繋留された船舶、建築物その他の工作物若しくはこれらに属するものをいう"],["複合用途防火対象物","防火対象物で政令で定める2以上の用途に供されるものをいう"],["高層建築物","高さ31mを超える建築物をいう"]]}],"3":[{"t":"tree","title":"消防用設備等の種類","root":"消防用設備等","branches":[["警報設備","警鐘、携帯用拡声器"],["避難設備","すべり台、避難はしご"],["消火活動上必要な施設","排煙設備、非常コンセント設備"]]},{"t":"tree","title":"基準改正後の防火対象物","root":"基準改正","branches":[["既存の防火対象物","改正前の基準にも適合していなかったもの"],["修繕・模様替え","基準改正後に、主要構造部の壁について1/2以上の修繕もしくは模様替えの工事を行った場合"],["既存の特定防火対象物","改正前の基準に適合していたもの"]]}],"7":[{"t":"tree","title":"消防設備士の義務","root":"消防設備士","branches":[["免状の携帯","その業務に従事するときは、消防設備士免状を携帯していなければならない"],["業務","その業務を誠実に行い、工事整備対象設備等の質の向上に努めなければならない"],["書換え","免状の記載事項に変更を生じたときは、書換えを申請しなければならない"],["講習","工事整備対象設備等の工事又は整備に関する講習を受講しなければならない"]]},{"t":"def","term":"書換え申請","text":"免状の記載事項に変更が生じた場合は、交付した都道府県知事又は居住地若しくは勤務地を管轄する都道府県知事に書換え申請を行う"},{"t":"def","term":"講習","text":"都道府県知事（総務大臣が指定する市町村長その他の機関を含む。）が行う工事整備対象設備等の工事又は整備に関する講習"},{"t":"table","title":"講習の受講時期","head":["区分","受講しなければならない時期"],"rows":[["最初","免状の交付を受けた日以後における最初の4月1日から2年以内"],["その後","受講日以後における最初の4月1日から5年以内ごと"]]}],"9":[{"t":"tree","title":"消火器具の設置基準","root":"消火器具","branches":[["設置場所","水その他消火剤が凍結し、変質し、又は噴出するおそれが少ない箇所に設ける"],["転倒防止","地震による震動等による転倒を防止するための適当な措置を講じる"],["小型消火器","防火対象物の各部分からの歩行距離が20m以下となるように設ける"],["大型消火器","設置する場合には、消火器具の能力単位数を1/2まで減少することができる"]]}]};
